        \
        --manual detection\
        local healthBar = unitFrame.healthBar\
        if (healthBar.CurrentHealth / healthBar.CurrentHealthMax <= envTable.ExecutePercent) then\
            envTable.UnitInExecuteRange (unitFrame)\
        end        \
        \
    else\
        \
        --auto detection\
        if (unitFrame.InExecuteRange) then\
            envTable.UnitInExecuteRange (unitFrame)\
        end\
        \
    end\
    \
end\
