					["Author"] = "Huugg-Valdrakken",
					["ConstructorCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\
    --insert code here\
    \
    local healthBar = unitFrame.healthBar\
    \
    if (not healthBar.absorbBar) then\
        healthBar.absorbBar = healthBar.FrameOverlay:CreateTexture(nil, \"overlay\")\
        healthBar.absorbBar:SetTexture([[Interface\\RaidFrame\\Shield-Fill]])\
        healthBar.absorbBar:Hide()\
    end\
    \
    if (not healthBar.absorbSpark) then\
        healthBar.absorbSpark = healthBar.FrameOverlay:CreateTexture(nil, \"overlay\")\
        healthBar.absorbSpark:SetTexture([[Interface\\CastingBar\\UI-CastingBar-Spark]])\
        healthBar.absorbSpark:SetBlendMode(\"ADD\")\
        healthBar.absorbSpark:Hide()\
    end\
    \
end\
\
\
\
\
",
