",
					["OnShowCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\
    if (not UnitGetTotalAbsorbs) then\
        return\
    end\
    \
    local healthBar = unitFrame.healthBar\
    \
    healthBar.absorbBar:Show()\
    healthBar.absorbSpark:Show()\
    \
    healthBar.absorbBar:SetTexture([[Interface\\RaidFrame\\Shield-Fill]])\
    \
    healthBar.absorbBar:ClearAllPoints()    \
    healthBar.absorbBar:SetPoint(\"topleft\", healthBar, \"topleft\", 0, 0)\
    healthBar.absorbBar:SetPoint(\"bottomleft\", healthBar, \"bottomleft\", 0, 0)\
    \
    healthBar.absorbBar:SetAlpha(1)\
    \
    healthBar.absorbBar.MaxValue = UnitGetTotalAbsorbs(unitId) or 0\
    healthBar.absorbBar.MinValue = 0\
end\
\
\
",
					["Options"] = {},
					["PlaterCore"] = 1,
					["Revision"] = 101,
					["ScriptType"] = 2,
					["SpellIds"] = {
						[1] = 373688,
						[2] = 391050,
					},
					["Time"] = 1669325411,
					["UpdateCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\
    \
    if (not UnitGetTotalAbsorbs) then\
        return\
    end\
    \
    local healthBar = unitFrame.healthBar\
    \
    healthBar.absorbBar:Show()\
    healthBar.absorbSpark:Show()\
    \
    local maxValue = healthBar.absorbBar.MaxValue\
    local currentValue = UnitGetTotalAbsorbs(unitId) or 0\
    \
    if (currentValue > 0) then\
        local minValue = 0\
        \
        local percent = currentValue / maxValue\
        healthBar.absorbBar:SetTexCoord(0, percent, 0, 1)\
        healthBar.absorbBar:SetWidth(percent * healthBar:GetWidth())\
        \
        healthBar.absorbSpark:SetPoint(\"left\", healthBar, \"left\", percent * healthBar:GetWidth() - 16, 0)\
        \
    else\
        healthBar.absorbBar:Hide()    \
        healthBar.absorbSpark:Hide()\
    end\
    \
    self.ThrottleUpdate = 0\
    \
end\
\
\
\
\
\
\
\
\
\
