				[29] = {
					["Author"] = "Tercioo-Sylvanas",
					["ConstructorCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\
    --castbar color (when can be interrupted)\
    envTable.CastbarColor = scriptTable.config.castbarColor\
    \
    --flash duration\
    local CONFIG_BACKGROUND_FLASH_DURATION = scriptTable.config.flashDuration\
    \
    --add this value to the cast bar height\
    envTable.CastBarHeightAdd = scriptTable.config.castBarHeight\
    \
    --create a fast flash above the cast bar\
    envTable.FullBarFlash = envTable.FullBarFlash or Plater.CreateFlash (self, 0.05, 1, \"white\")\
    \
    --create a camera shake for the nameplate\
    envTable.FrameShake = Plater:CreateFrameShake (unitFrame, scriptTable.config.shakeDuration, scriptTable.config.shakeAmplitude, scriptTable.config.shakeFrequency, false, false, 0, 1, 0.05, 0.1, Plater.GetPoints (unitFrame))\
    \
    --create a texture to use for a flash behind the cast bar\
    self.simpleInterruptFlash = self.simpleInterruptFlash or  Plater:CreateImage (self, [[Interface\\ACHIEVEMENTFRAME\\UI-Achievement-Alert-Glow]], self:GetWidth()+60, self:GetHeight()+50, \"background\", {0, 400/512, 0, 170/256})\
    \
    self.simpleInterruptFlash:SetBlendMode (\"ADD\")\
    self.simpleInterruptFlash:SetDrawLayer(\"OVERLAY\", 7)\
    self.simpleInterruptFlash:SetPoint (\"center\", self, \"center\")\
    self.simpleInterruptFlash:Hide()\
    \
    --create the animation hub to hold the flash animation sequence\
    self.simpleInterruptFlashAnimHub = self.simpleInterruptFlashAnimHub or Plater:CreateAnimationHub (self.simpleInterruptFlash, \
        function()\
            self.simpleInterruptFlash:Show()\
        end,\
        function()\
            self.simpleInterruptFlash:Hide()\
        end\
    )\
    \
    --create the flash animation sequence\
    self.simpleInterruptFlashAnimHub.fadeIn = self.simpleInterruptFlashAnimHub.fadeIn or Plater:CreateAnimation (self.simpleInterruptFlashAnimHub, \"ALPHA\", 1, CONFIG_BACKGROUND_FLASH_DURATION/2, 0, .75)\
    self.simpleInterruptFlashAnimHub.fadeIn:SetDuration(CONFIG_BACKGROUND_FLASH_DURATION/2)\
    \
    self.simpleInterruptFlashAnimHub.fadeOut = self.simpleInterruptFlashAnimHub.fadeOut or Plater:CreateAnimation (self.simpleInterruptFlashAnimHub, \"ALPHA\", 2, CONFIG_BACKGROUND_FLASH_DURATION/2, 1, 0)    \
    self.simpleInterruptFlashAnimHub.fadeOut:SetDuration(CONFIG_BACKGROUND_FLASH_DURATION/2)\
    \
    --envTable.BackgroundFlash:Play() --envTable.BackgroundFlash:Stop()    \
    \
    \
    \
    \
    \
end\
\
\
",
