				[44] = {
					["Author"] = "Huugg-Valdrakken",
					["ConstructorCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\
    \
    function envTable.CreateWidgets()\
        --create a camera shake for the nameplate\
        if (not unitFrame.AddExplosionOnDieShake) then\
            unitFrame.AddExplosionOnDieShake = Plater:CreateFrameShake (unitFrame, scriptTable.config.shakeDuration, scriptTable.config.shakeAmplitude, scriptTable.config.shakeFrequency, false, false, 0, 1, 0.05, 0.1, Plater.GetPoints (unitFrame))\
        end\
        \
        if (not unitFrame.AddExplosionOnDieBackground) then\
            unitFrame.AddExplosionOnDieBackground = unitFrame.healthBar:CreateTexture(nil, \"background\")\
            unitFrame.AddExplosionOnDieBackground:SetAllPoints(unitFrame.healthBar)\
            unitFrame.AddExplosionOnDieBackground:SetColorTexture(1, 0, 0, 1)\
        end\
    end\
    \
end\
