        local _, class = UnitClass (unitId .. \"target\");\
        targetName = Plater.SetTextColorByClass (unitId .. \"target\", targetName);\
        envTable.FixateTarget.text = targetName;\
        \
        envTable.FixateTarget:Show();\
        envTable.FixateIcon:Show();\
    end    \
